import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readdir, readFile } from "node:fs/promises";
import { join, dirname, basename } from "node:path";
import { fileURLToPath } from "node:url";
import { analyzeText } from "./index.js";

// Deterministic baseline: goldens capture the FALLBACK path on every machine
// (clang-equipped CI asserts against the compiler oracle in layout-truth.test.ts
// instead). Change-detection goldens are generated by gen-goldens and must be
// human-reviewed on every regen — they are tripwires, not oracles.
const REAL_CLANG_ENV = process.env["MEMLENS_CLANG"];

const here = dirname(fileURLToPath(import.meta.url));
const fixturesDir = join(here, "..", "..", "..", "fixtures");

describe("fixture goldens", () => {
  it("every fixture matches its golden snapshot", async () => {
    process.env["MEMLENS_CLANG"] = "definitely-not-a-compiler-xyz";
    try {
    const files = (await readdir(fixturesDir)).filter((f) => f.endsWith(".cpp")).sort();
    assert.ok(files.length >= 10, `expected fixtures, found ${files.length}`);
    for (const f of files) {
      const text = await readFile(join(fixturesDir, f), "utf8");
      const uri = `file:///fixtures/${f}`;
      const res = await analyzeText({ requestId: "golden-check", uri, docVersion: 1, text, languageId: "cpp", fidelity: "static" });
      const golden = JSON.parse(await readFile(join(fixturesDir, "expected", `${basename(f, ".cpp")}.snapshot.json`), "utf8"));
      const actual = { ...res.snapshot, id: "golden", timestamp: 0 };
      assert.deepEqual(actual, golden, `golden mismatch: ${f} (regen with npm run gen-goldens -w @memlens/analysis)`);
    }
    } finally {
      if (REAL_CLANG_ENV === undefined) delete process.env["MEMLENS_CLANG"];
      else process.env["MEMLENS_CLANG"] = REAL_CLANG_ENV;
    }
  });
});
